import { useEffect, useState } from 'react';
import ProgressBar from '../components/ProgressBar';

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({
    consistency: 0,
    quiz: 0,
    tasks: 0,
  });

  const [streak, setStreak] = useState(0);
  const [xp, setXP] = useState(0);
  const [level, setLevel] = useState(1);
  const [recommendation, setRecommendation] = useState("");

  useEffect(() => {
    const quizScore = parseInt(localStorage.getItem('quizScore') || '0');
    const totalQuestions = parseInt(localStorage.getItem('totalQuestions') || '1');
    const quizPercentage = Math.round((quizScore / totalQuestions) * 100);

    const completed = parseInt(localStorage.getItem('lastCompletedCount') || '0');
    const totalTasks = parseInt(localStorage.getItem('lastTotalTasks') || '1');
    const taskPercentage = Math.round((completed / totalTasks) * 100);

    const completedDays = JSON.parse(localStorage.getItem('completedDays') || '[]');
    const currentDay = parseInt(localStorage.getItem('currentDay') || '1');

    const consistency = Math.round((completedDays.length / currentDay) * 100);

    // 🔥 Streak
    let currentStreak = 0;
    const sortedDays = [...completedDays].sort((a, b) => a - b);

    for (let i = sortedDays.length - 1; i >= 0; i--) {
      if (sortedDays[i] === currentDay - currentStreak - 1) {
        currentStreak++;
      } else break;
    }

    // 🎮 XP + Level
    const totalXP = parseInt(localStorage.getItem("xp") || "0");
    const userLevel = Math.floor(totalXP / 100) + 1;

    // 🤖 AI Recommendation
    const generateRecommendation = ({ tasks, quiz, consistency }) => {
      if (tasks < 50) return "⚡ Focus on completing daily tasks.";
      if (quiz < 60) return "🧠 Revise fundamentals and retry quizzes.";
      if (consistency < 70) return "📅 Improve daily consistency.";
      if (tasks > 80 && quiz > 80) return "🚀 You're ahead! Start projects.";
      return "👍 Keep going! You're doing well.";
    };

    setMetrics({ consistency, quiz: quizPercentage, tasks: taskPercentage });
    setStreak(currentStreak);
    setXP(totalXP);
    setLevel(userLevel);
    setRecommendation(generateRecommendation({ tasks: taskPercentage, quiz: quizPercentage, consistency }));
  }, []);

  return (
    <div className="space-y-8">

      {/* 🔥 Header */}
      <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
        <h2 className="text-3xl font-semibold text-slate-900 dark:text-slate-50">
          🚀 Your Progress Dashboard
        </h2>
        <p className="mt-2 text-slate-600 dark:text-slate-300">
          Track your learning, level up, and stay consistent.
        </p>
      </div>

      {/* 🎮 XP + Level */}
      <div className="grid gap-6 md:grid-cols-2">
        <div className="rounded-[2rem] border bg-gradient-to-br from-purple-100 to-purple-50 p-6 shadow-md dark:from-slate-700 dark:to-slate-700">
          <h3 className="text-lg font-semibold">🎮 Total XP</h3>
          <p className="mt-2 text-3xl font-bold">{xp} XP</p>
        </div>

        <div className="rounded-[2rem] border bg-gradient-to-br from-green-100 to-green-50 p-6 shadow-md dark:from-slate-700 dark:to-slate-700">
          <h3 className="text-lg font-semibold">🏆 Level</h3>
          <p className="mt-2 text-3xl font-bold">Level {level}</p>
        </div>
      </div>

      {/* 📊 Metrics */}
      <div className="grid gap-6 xl:grid-cols-3">
        <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-6 shadow-md dark:from-slate-800 dark:to-slate-800">
          <ProgressBar label="Consistency" value={metrics.consistency} />
        </div>

        <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-6 shadow-md dark:from-slate-800 dark:to-slate-800">
          <ProgressBar label="Quiz Mastery" value={metrics.quiz} />
        </div>

        <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-6 shadow-md dark:from-slate-800 dark:to-slate-800">
          <ProgressBar label="Task Completion" value={metrics.tasks} />
        </div>
      </div>

      {/* 🔥 Streak */}
      <div className="rounded-[2rem] bg-gradient-to-br from-teal-100 to-blue-100 p-8 shadow-md dark:from-slate-700 dark:to-slate-700">
        <h3 className="text-xl font-semibold">🔥 Current Streak</h3>
        <p className="mt-2 text-5xl font-bold">{streak} days</p>
      </div>

      {/* 🤖 AI Recommendation */}
      <div className="rounded-[2rem] border bg-gradient-to-br from-yellow-100 to-orange-50 p-6 shadow-md dark:from-slate-700 dark:to-slate-700">
        <h3 className="text-lg font-semibold">🤖 Smart Recommendation</h3>
        <p className="mt-2 text-slate-700 dark:text-slate-300">
          {recommendation}
        </p>
      </div>

    </div>
  );
}
